using System.Data.Common;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;
using Microsoft.Extensions.DependencyInjection;
using Sem.Authentication;
using Sem.Web.Core;
using Sem.Web.Data;
using Sem.Web.Runtime;
int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;}var file=Path.Combine(Path.GetTempPath(),"sem-public-answers-"+Guid.NewGuid().ToString("N")+".db");var now=DateTimeOffset.Parse("2026-10-26T00:00:00Z");
try{
 var sql=new ProjectionCapture();var services=new ServiceCollection();services.AddLogging();services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+file).AddInterceptors(sql));services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();await using var provider=services.BuildServiceProvider();await using var scope=provider.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();await SqliteStorageInitializer.InitializeAsync(db);db.Users.Add(new(){Id="synthetic-user",UserName="synthetic@example.invalid",Email="synthetic@example.invalid",DisplayName="合成管理者",Enabled=true,EmailConfirmed=true,SecurityStamp="stamp"});await db.SaveChangesAsync();await EventListFixture.Seed(db);await EventDetailFixture.Seed(db);await PublicAnswerFixture.Seed(db);
 var identity=new IdentityOptions();ClaimsPrincipal Who(string stamp="stamp",bool duplicate=false)=>new(new ClaimsIdentity(new[]{new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user"),new Claim(identity.ClaimsIdentity.SecurityStampClaimType,stamp),new Claim(AuthenticationSession.SessionClaim,"session"),new Claim(ClaimTypes.Role,"ServiceAdmin")}.Concat(duplicate?[new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user")]:[]),"synthetic"));Task<EventDetailResult> Read(string id="public",ClaimsPrincipal? who=null)=>EventDetailReader.ReadAsync(db,who??Who(),identity,id,now);
 var before=File.ReadAllBytes(file);var wal=File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[];sql.PrivateSelections.Clear();var r=await Read();var q=r.View!.PublicAnswers;
 Check(r.State=="ok"&&q.Length==4,"公開・使用中・未削除の設問だけ");Check(q.Select(x=>x.Id).SequenceEqual(new[]{"summary-yn","summary-text","summary-private","summary-empty"}),"設問の保存順を維持");var yn=q[0];Check(yn.AnsweredCount==3&&yn.Groups.Select(g=>g.Value).SequenceEqual(new[]{"YES","NO"}),"YES／NOだけを分母にする");Check(yn.Groups[0].Count==2&&yn.Groups[1].Count==1,"割合に使う人数を正しく集計");Check(!yn.PublicText&&yn.Groups[0].Respondents.Length==2,"回答者の現在表示名とIDを最小投影");Check(yn.Groups.SelectMany(g=>g.Respondents).All(p=>p.Id!="synthetic-invalid"),"不正なYesNo値は集計しない");Check(q[1].PublicText&&q[1].Groups.Length==2&&q[1].Groups[0].Value=="<img src=x> 希望A"&&q[1].Groups[0].Count==2&&q[1].Groups[1].Count==1,"公開本文の同値グループと人数尺度");Check(q[1].AnsweredCount==3,"Unicode空白だけの公開回答は未回答");Check(!q[2].PublicText&&q[2].Groups.Single().Value is null&&q[2].AnsweredCount==2,"非公開本文はnull・人数だけ");Check(sql.PrivateSelections.Count==1&&sql.PrivateSelections.All(s=>!s.Contains("\"Value\"")),"本文非公開の結果SQL列にValueを含めない");Check(q[3].AnsweredCount==0&&q[3].Groups.All(g=>g.Count==0),"0人と未読取失敗を分離");
 var json=JsonSerializer.Serialize(q);foreach(var secret in new[]{"PRIVATE_QUESTION_SENTINEL","PRIVATE_ANSWER_SENTINEL","PRIVATE_TEXT_SENTINEL","PRIVATE_DISABLED","PRIVATE_DELETED","PRIVATE_HIDDEN","PRIVATE_UNUSED","@example.invalid","SecurityStamp","Email","RowVersion"})Check(!json.Contains(secret),"私的・別イベント・停止情報を含めない "+secret);
 Check(before.SequenceEqual(File.ReadAllBytes(file))&&wal.SequenceEqual(File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[]),"集計参照でDB／WAL不変");Check((await Read("hidden")).State=="not-found","古い管理role claimで担当外非公開を読めない");Check((await Read(who:new(new ClaimsIdentity()))).State=="unauthorized","匿名拒否");Check((await Read(who:Who("old"))).State=="unauthorized","stamp不一致拒否");Check((await Read(who:Who(duplicate:true))).State=="unauthorized","多重本人claim拒否");
 var text=await db.EventQuestions.SingleAsync(x=>x.Id=="summary-text");text.PublicText=false;await db.SaveChangesAsync();Check((await Read()).View!.PublicAnswers.Single(x=>x.Id==text.Id).Groups.Single().Value is null,"本文公開解除で即時に本文を除去");text.Public=false;await db.SaveChangesAsync();Check((await Read()).View!.PublicAnswers.All(x=>x.Id!=text.Id),"設問公開解除でグループと回答者も除去");var yes=await db.EventQuestions.SingleAsync(x=>x.Id=="summary-yn");yes.Disabled=true;await db.SaveChangesAsync();Check((await Read()).View!.PublicAnswers.All(x=>x.Id!=yes.Id),"停止後は公開回答を残さない");
 var actor=await db.Users.SingleAsync(x=>x.Id=="synthetic-user");actor.Enabled=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","本人無効化で集計も拒否");actor.Enabled=true;await db.SaveChangesAsync();db.RevokedAuthSessions.Add(new(){UserId=actor.Id,TokenHash=AuthenticationSession.Hash("session"),RevokedAt=now.ToString("O")});await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","session失効で集計も拒否");Console.WriteLine($"公開回答・SQL私的本文除外・現在認可 {checks}検査: 成功（合成DBのみ）");
}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();foreach(var p in new[]{file,file+"-wal",file+"-shm"})File.Delete(p);}
sealed class ProjectionCapture:DbCommandInterceptor {
 public List<string> PrivateSelections {get;}=[];
 public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData e,InterceptionResult<DbDataReader> r,CancellationToken ct=default){if(c.CommandText.StartsWith("SELECT")&&c.CommandText.Contains("EventQuestionAnswers")&&c.Parameters.Cast<DbParameter>().Any(p=>Equals(p.Value,"summary-private"))){var i=c.CommandText.IndexOf("FROM",StringComparison.Ordinal);if(i>0)PrivateSelections.Add(c.CommandText[..i]);}return ValueTask.FromResult(r);}
}
